mapper.update:
UPDATE auth_user
SET last_login_time = CURRENT_TIMESTAMP, failed_attempts = 0, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT * FROM auth_user
username LIKE CONCAT('%', #{keyword}, '%') OR email LIKE CONCAT('%', #{keyword}, '%') OR display_name LIKE CONCAT('%', #{keyword}, '%')
ORDER BY ${orderBy} ${orderDir}
ORDER BY id
LIMIT #{limit} OFFSET #{offset}
